import { loadJSON } from '../data.js';
import { exportLinks } from '../export.js';

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const a = (url, text) => (url ? `<a href="${esc(url)}" target="_blank" rel="noopener">${esc(text ?? url)}</a>` : esc(text));

// References: generated by scripts/05_build_references.py from what the pipeline and site use (same content as references.md).
const GROUPS = [['psi', 'NASA data (PSI)'], ['papers', 'Reports and papers'], ['challenge', 'Challenge'], ['media', 'Images and video'],
  ['software', 'Software'], ['services', 'Services'], ['export', 'Data export'], ['ai', 'Use of AI']];
const grp = (id, title, count, body, open = false) => `<details class="lgroup" id="ref-${id}"${open ? ' open' : ''}><summary><h3>${title}</h3><span class="lcount">${count}</span></summary>${body}</details>`;

export async function render(root, arg) {
  const [r, dl] = await Promise.all([loadJSON('references.json'), exportLinks()]);
  const c = r.challenge;
  root.innerHTML = `
  <section class="card"><h2>References</h2>
    <p class="note">Every external resource this site uses, generated from the pipeline's own inputs (also in the repository as references.md).</p>

    <nav class="jump" aria-label="Reference groups">${GROUPS.map(([id, t]) => `<a href="#references/${id}">${t}</a>`).join('')}<button type="button" class="expandall">Expand all</button></nav>
    ${grp('psi', 'NASA data: Physical Sciences Informatics (PSI)', `${r.psi.investigations.length} datasets`, `<p class="note">${a(r.psi.repository.url, r.psi.repository.title)}. ${esc(r.psi.note)}</p>
    <div class="scroll"><table class="stack"><thead><tr><th>PSI ID</th><th>Investigation</th><th>Dataset DOI</th><th>Files used</th></tr></thead><tbody>
    ${r.psi.investigations.map((i) => `<tr><td class="nowrap">${esc(i.psi_id)}</td><td>${esc(i.title)}</td><td>${i.doi ? a(i.url, i.doi) : 'none in metadata'}</td>
      <td class="small">${i.files_used.map(esc).join('<br>')}</td></tr>`).join('')}
    </tbody></table></div>`, true)}
    ${grp('papers', 'Reports and papers', `${r.papers.length}`, `<ul class="refs">${r.papers.map((p) => `<li>${esc(p.citation.replace(/\.$/, ''))}. ${p.ntrs_id ? `NTRS ${esc(p.ntrs_id)}: ` : ''}${a(p.url)}${p.pdf_url && p.pdf_url !== p.url ? ` (${a(p.pdf_url, 'PDF')})` : ''}.
      ${p.cited_pages.length ? `Pages cited: ${p.cited_pages.map((x) => `p.${x}`).join(', ')}.` : 'No page numbers (abstract record).'}</li>`).join('')}</ul>`)}
    ${grp('challenge', 'Challenge', `${2 + c.resources_used.length}`, `<ul class="refs"><li>${a(c.page.url, c.page.title)} (text saved in ${esc(c.page.saved_copy)}).</li>
      <li>${esc(c.video.title)}${c.video.url ? `: ${a(c.video.url)}` : ''}. ${esc(c.video.note)}</li>
      ${c.resources_used.map((x) => `<li>${a(x.url, x.title)}${x.note ? `: ${esc(x.note)}` : ''}</li>`).join('')}</ul>`)}
    ${grp('media', 'Images and video', `${r.media.length}`, `<ul class="refs">${r.media.map((m) => `<li>${esc(m.what)}. Credit: ${esc(m.credit)}.</li>`).join('')}</ul>`)}
    ${grp('software', 'Software', `${r.software.npm.length + r.software.python.length} packages`, `<div class="scroll"><table><thead><tr><th>Package</th><th>Version</th><th>Licence</th><th>Used for</th></tr></thead><tbody>
    ${[...r.software.npm, ...r.software.python].map((s) => `<tr><td>${a(s.url, s.name)}</td><td>${esc(s.version)}</td><td>${esc(s.license ?? 'see package')}</td><td>${esc(s.use)}</td></tr>`).join('')}
    </tbody></table></div>
    <ul class="refs">${r.software.tools.map((t) => `<li>${esc(t.name)}: ${esc(t.use)}.</li>`).join('')}</ul>`)}
    ${grp('services', 'Services', `${r.services.length}`, `<ul class="refs">${r.services.map((s) => `<li>${a(s.url, s.name)}: ${esc(s.use)}.</li>`).join('')}</ul>`)}
    ${grp('export', 'Data export (this site\'s own output)', `${dl.length} files`, `<p class="note">The tests this site places, as CSV with a source on every row, generated by scripts/05_build_export.py. Cite the NASA DOIs above when you use them.</p>
    <ul class="refs">${dl.map((x) => `<li>${x}</li>`).join('')}</ul>`, true)}
    ${grp('ai', 'Use of AI', 'statement', `<p>${esc(r.ai_statement)}</p>`, true)}
  </section>`;
  const all = [...root.querySelectorAll('details.lgroup')];
  const btn = root.querySelector('.expandall');
  const sync = () => { btn.textContent = all.every((d) => d.open) ? 'Collapse all' : 'Expand all'; };
  btn.addEventListener('click', () => { const open = !all.every((d) => d.open); all.forEach((d) => { d.open = open; }); sync(); });
  all.forEach((d) => d.addEventListener('toggle', sync));
  const want = arg && root.querySelector(`#ref-${CSS.escape(arg)}`);
  if (want) { want.open = true; want.dataset.goto = ''; want.tabIndex = -1; }
  sync();
}
